/** Dated live evidence is read and verified, never regenerated by a keyless run. */
import { readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { canonicalSha256 } from '@jarenjs/json/canonical';
import { validatePrihaLive } from './priha-live.ts';
import type { PrihaLivePlan, PrihaLiveExecution } from './priha.types.ts';

export interface PrihaLiveReceipt { plan: PrihaLivePlan; execution: PrihaLiveExecution }
export async function readPrihaLiveReceipts(root = process.cwd()): Promise<PrihaLiveReceipt[]> {
    const directory = join(root, 'benchmark/results'), receipts: PrihaLiveReceipt[] = [];
    for (const name of (await readdir(directory)).filter(name => /^priha-live-\d{4}-\d{2}-\d{2}-[a-f0-9]{64}\.json$/.test(name)).sort()) {
        const receipt = JSON.parse(await readFile(join(directory, name), 'utf8')) as PrihaLiveReceipt;
        validatePrihaLive(receipt.plan); validatePrihaLive(receipt.execution);
        const { planId, ...plan } = receipt.plan.plan, { executionId, ...execution } = receipt.execution;
        if (planId !== await canonicalSha256(plan) || executionId !== await canonicalSha256(execution)
            || execution.planId !== planId || execution.sourceSha256 !== plan.sourceSha256 || execution.registrationId !== plan.registrationId
            || name !== `priha-live-${execution.at.slice(0, 10)}-${executionId}.json`)
            throw Error('PriHA live receipt identity mismatch: ' + name);
        receipts.push(receipt);
    }
    return receipts;
}
